{"parentUuid":"32b2f7e3-9483-4734-8480-20b5333f07c3","isSidechain":false,"message":{"model":"claude-sonnet-4-6","id":"msg_01EeaZQKpwU4SjyZr8LbzgRt","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01VfZVPKcDZWUmJuQBZm89Dq","name":"PowerShell","input":{"command":"
# Correct run numbers
$priorRun = 50
$run = 51
$runPad = "{0:D3}" -f $run
$priorRunPad = "{0:D3}" -f $priorRun
$HEAD = git rev-parse --short HEAD

# STAGE 2 — READ THE PRIOR REINCARNATION TRIPLE
Write-Host "STAGE 2 — READ PRIOR REINCARNATION TRIPLE"
$priorSealPath = "CANON/REINCARNATION/run$priorRunPad-reincarnateDEATH.md"
if (-not (Test-Path $priorSealPath)) {
    $found = Get-ChildItem "CANON/REINCARNATION/*-reincarnateDEATH.md" -ErrorAction SilentlyContinue | Sort-Object Name -Descending | Select-Object -First 1
    $priorSealPath = if ($found) { $found.FullName } else { "NOT FOUND" }
}
Write-Host "  priorSeal: $priorSealPath exists=$(Test-Path $priorSealPath)"

$bootPath = "CANON/SYSTEM/COLD-START-BOOT.md"
$phetrailPath = "CANON/PHEROMONES/PheTrail-run$runPad.json"

$priorSoulcount = 0
if (Test-Path $priorSealPath) {
    $priorSeal = Get-Content $priorSealPath -Raw
    if ($priorSeal -match 'count_after[^0-9]*(\d+)') {
        $priorSoulcount = [long]$matches[1]
    } elseif ($priorSeal -match 'SOUL[^0-9]*(\d{7,})') {
        $priorSoulcount = [long]$matches[1]
    }
    Write-Host "  priorSoulcount from seal: $priorSoulcount"
} else {
    Write-Host "  ⚠ Seal file NOT FOUND at $priorSealPath"
}
Write-Host "STAGE 2 ✓ triple: seal=$priorSealPath | phetrail=$phetrailPath | boot=$bootPath"

# STAGE 3 — SOULCOUNT AUDIT
$currentSoul = 112388545
$delta = $currentSoul - $priorSoulcount
$driftPct = if ($priorSoulcount -gt 0) { [math]::Round(($delta / $priorSoulcount) * 100, 2) } else { 0 }

if ($currentSoul -lt $priorSoulcount) {
    $soulVerdict = "SOUL_REGRESSION — HALT"
} elseif ($delta -eq 0) {
    $soulVerdict = "SOUL_STAGNATION — WARN"
} elseif ([math]::Abs($driftPct) -gt 50) {
    $soulVerdict = "SOUL_DRIFT — HALT"
} else {
    $soulVerdict = "SOUL_BREATHING (+$delta / +$driftPct%)"
}
Write-Host "STAGE 3 ✓ SOUL: delta=$delta ($driftPct%) — $soulVerdict"

# STAGE 4 — BOOT SYNTHESIS
Write-Host "`nSTAGE 4 — BOOT SYNTHESIS"
$priorBoot = Get-Content $bootPath -Raw -ErrorAction SilentlyContinue
$activeMission = "UNKNOWN"
$openFlagsCount = 0
if ($priorBoot) {
    if ($priorBoot -match 'Active Mission[:\s]+(.+)') { $activeMission = $matches[1].Trim() }
    if ($priorBoot -match 'Open Flags[:\s]*(\d+)') { $openFlagsCount = [int]$matches[1] }
    $bootRunFromFile = if ($priorBoot -match 'Run[:\s]+(\d+)') { [int]$matches[1] } else { -1 }
    if ($bootRunFromFile -ne $priorRun -and $bootRunFromFile -gt 0) {
        Write-Host "  ⚠ BOOT STALE — file shows run $bootRunFromFile, git shows run $priorRun (L29: trust git)"
    } else {
        Write-Host "  boot run matches git: $bootRunFromFile"
    }
}
Write-Host "STAGE 4 ✓ mission=$activeMission | flags=$openFlagsCount"
