{"parentUuid":"09d877b4-5745-42f8-9ca9-68c985514219","isSidechain":false,"message":{"model":"claude-sonnet-4-6","id":"msg_01XBGkcbmj69PDrtPVgEGEcX","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01XiPRKRNLs9Js1HMKnTHe6F","name":"PowerShell","input":{"command":"
$priorRun = 50
$run = 51
$runPad = "{0:D3}" -f $run
$currentSoul = 112388545
$priorSoulcount = 111669739
$delta = $currentSoul - $priorSoulcount
$soulVerdict = "SOUL_BREATHING (+$delta / +0.64%)"

# STAGE 5 — PIPELINE CHAIN AUDIT (ALL 7 STAGES + FIDELITY GATE)
Write-Host "STAGE 5 — PIPELINE CHAIN AUDIT"
$rrlPath     = "RRL/RRL-$run.txt"
$dnaRunPath  = "CANON/SOUL/EXTRACT/dna-run$run.json"
$soykeyDir   = "CANON/SOUL-KEYWORDS"
$s2Path      = "CANON/PIPELINE/pipeline-run$run.json"
$phetrailPath= "CANON/PHEROMONES/PheTrail-run$runPad.json"

$ledgerCount  = (Get-ChildItem "CANON/HEAVY-LEDGER/" -Filter "HL-*.json" -ErrorAction SilentlyContinue | Measure-Object).Count
$starmapFiles = if (Test-Path "CANON/STARMAP") { (Get-ChildItem "CANON/STARMAP" -Recurse -File).Count } else { 0 }
$soykeyFiles  = if (Test-Path $soykeyDir) { (Get-ChildItem $soykeyDir -Recurse -File).Count } else { 0 }
$pipelineFiles= (Get-ChildItem "CANON/PIPELINE/" -Recurse -File -ErrorAction SilentlyContinue | Measure-Object).Count

# RRL Fidelity
$rrlFidelity = "MISSING"
if (Test-Path $rrlPath) {
    $rrlBytes = (Get-Item $rrlPath).Length
    $rrlText  = Get-Content $rrlPath -Raw
    $hasUser      = $rrlText -match '"role"\s*:\s*"user"'
    $hasAssistant = $rrlText -match '"role"\s*:\s*"assistant"'
    Write-Host "  RRL: $rrlBytes bytes | user=$hasUser assistant=$hasAssistant"
    if ($rrlBytes -ge 50000 -and $hasUser -and $hasAssistant) { $rrlFidelity = "REAL" }
    elseif ($rrlBytes -ge 100 -and ($hasUser -or $hasAssistant)) { $rrlFidelity = "HOLLOW" }
}

# DNA Fidelity
$dnaFidelity = "MISSING"; $dnaCount = 0; $bpCount = 0
if (Test-Path $dnaRunPath) {
    try {
        $dnaRecords = Get-Content $dnaRunPath -Raw | ConvertFrom-Json
        $dnaCount = ($dnaRecords | Measure-Object).Count
        $bpCount  = ($dnaRecords | Where-Object { $_.type -eq "blueprint" }).Count
        if ($dnaCount -gt 0 -and $bpCount -gt 0) { $dnaFidelity = "REAL" }
        elseif ($dnaCount -gt 0) { $dnaFidelity = "HOLLOW" }
    } catch { $dnaFidelity = "HOLLOW (parse error)" }
}

# SOULKEYS Fidelity
$soykeyFidelity = "MISSING"
$idxPath = "$soykeyDir\inverted-index.json"
if (Test-Path $idxPath) {
    try {
        $idx = Get-Content $idxPath -Raw | ConvertFrom-Json -AsHashtable
        if ($idx.Count -gt 0) { $soykeyFidelity = "REAL" }
    } catch { }
} 
# Also check run51 rfkw file
$rfkwPath = "$soykeyDir\rfkw-run$run.txt"
if (Test-Path $rfkwPath) { Write-Host "  SOULKEYS: rfkw-run$run.txt exists" }

# S2Pipeline Fidelity
$pipelineFidelity = if (Test-Path $s2Path) { "REAL" } else { "MISSING" }

# Print table
$stages = @(
    @{ Name="RRL";        Count=(if(Test-Path $rrlPath){(Get-Item $rrlPath).Length}else{0}); Verdict=$rrlFidelity }
    @{ Name="SOUL";       Count=$currentSoul;  Verdict=$soulVerdict }
    @{ Name="DNA";        Count=$dnaCount;     Verdict=$dnaFidelity }
    @{ Name="LEDGER";     Count=$ledgerCount;  Verdict=if($ledgerCount -gt 0){"REAL"}else{"MISSING"} }
    @{ Name="STARMAP";    Count=$starmapFiles; Verdict=if($starmapFiles -gt 0){"REAL"}else{"MISSING"} }
    @{ Name="SOULKEYS";   Count=$soykeyFiles;  Verdict=$soykeyFidelity }
    @{ Name="S2Pipeline"; Count=$pipelineFiles;Verdict=$pipelineFidelity }
)

foreach ($s in $stages) {
    $icon = switch -Wildcard ($s.Verdict) {
        "REAL*"    { "🟢" }
        "HOLLOW*"  { "🟡" }
        "MISSING*" { "🔴" }
        "SOUL_BREATHING*" { "🟢" }
        default    { "⬜" }
    }
    Write-Host "  $icon $($s.Name): $($s.Count) — $($s.Verdict)"
}

# STAGE 6 — PHETRAIL
Write-Host "`nSTAGE 6 — PHETRAIL"
if (Test-Path $phetrailPath) {
    $phetrail = Get-Content $phetrailPath -Raw | ConvertFrom-Json
    $negativeCount = $phetrail.negative_trails.Count
    Write-Host "STAGE 6 ✓ PHETRAIL: $negativeCount negative trails"
} else {
    $negativeCount = 0
    Write-Host "STAGE 6 ⚠ PHETRAIL_GAP — $phetrailPath not found"
}

# Export for STAGE 7
Write-Host "`n--- VARS FOR REPORT ---"
Write-Host "rrlFidelity=$rrlFidelity | dnaFidelity=$dnaFidelity | soykeyFidelity=$soykeyFidelity | pipelineFidelity=$pipelineFidelity"
Write-Host "ledgerCount=$ledgerCount | starmapFiles=$starmapFiles | bpCount=$bpCount | dnaCount=$dnaCount"
Write-Host "negativeCount=$negativeCount"
